fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len() as u8; // Get the length of the original vector as u8
    if orig_len >= width {
        // If the original length is greater than or equal to the target width, return it unchanged
        return orig;
    }

    // Calculate the number of fill characters needed
    let fill_count = width - orig_len;
    
    // Create a new vector with the fill characters followed by the original characters
    let mut res = vec![fillchar; fill_count as usize]; // Fill with the fill character
    res.extend(orig); // Append the original characters

    res // Return the new vector
}